    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; ++tile) {
        // Load A and B tiles into shared memory
        int a_load_row = row;
        int a_load_col = tile * BLOCK_SIZE + threadIdx.x;
        if (a_load_row < N && a_load_col < N) {
            As[threadIdx.y][threadIdx.x] = A[a_load_row * N + a_load_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside bounds
        }

        int b_load_row = tile * BLOCK_SIZE + threadIdx.y;
        int b_load_col = col;
        if (b_load_row < N && b_load_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_load_row * N + b_load_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside bounds
